/* allow full-page-width map */
.dnd-section .dnd-column:has(#hs_cos_wrapper_widget_1743125355601) {
  padding: 0;
}

.mySlides {
  display: none;
  margin: 0;
}
img { vertical-align: middle; }

/* Slideshow container */
.slideshow-container {
  max-width: 1000px;
  position: relative;
  margin: 0 auto 2rem;
}

/* Next & previous buttons */
.prev, .next {
  cursor: pointer;
  position: absolute;
  top: 50%;
  width: auto;
  padding: 16px;
  margin-top: -1.5rem;
  background-color: rgba(255,255,255,0.8);
  color: #254080;
  font-weight: bold;
  font-size: 1rem;
  transition: 0.6s ease;
  border: none;
  border-radius: 0 3px 3px 0;
  user-select: none;
}
.prev {
  left: 0;
}
.next {
  right: 0;
  border-radius: 3px 0 0 3px;
}
.prev:hover, .next:hover {
  background-color: rgba(37,64,128,0.8);
  color: #ff914d;
}
.prev:focus, .next:focus {
  outline: none;
}

figcaption, .numbertext {
  background-color: rgba(37,64,128,0.8);
  color: #f2f2f2;
  font-size: .8rem;
  padding: .5rem .75rem;
  position: absolute;
}
figcaption {
  bottom: .5rem;
  width: 100%;
  text-align: center;
}
.numbertext {
  top: 0;
}

/* Thumbnail navigation styling */
.thumbnail-list {
  list-style-type: none;
  margin: 0;
  padding: 0;
  text-align: center;
}
.thumbnail-list li {
  display: inline-block;
}
.thumbnail {
  cursor: pointer;
  width: 80px;
  height: 80px;
  margin: 0 2px;
  display: inline-block;
  object-fit: cover;
  opacity: 0.6;
  transition: opacity 0.6s ease, border 0.6s ease;
  border: 2px solid transparent;
}
.thumbnail:hover,
.thumbnail.active {
  opacity: 1;
  border-color: #ff914d;
}

/* Fading animation */
.fade {
  animation-name: fade;
  animation-duration: 1.5s;
}
@keyframes fade {
  from { opacity: .4; }
  to { opacity: 1; }
}
@media only screen and (min-width: 480px) {
  .prev, .next {
    font-size: 2rem;
    margin-top: -2rem;
  }
  figcaption { font-size: 1rem; }
}

sourceGalleryScript:
let slideIndex = 1;
document.addEventListener('DOMContentLoaded', function() {
  const slides = document.querySelectorAll('.slideshow-container .mySlides');
  const totalSlides = slides.length;
  slides.forEach((slide, index) => {
    const numberText = document.createElement('div');
    numberText.className = 'numbertext';
    numberText.textContent = (index + 1) + ' / ' + totalSlides;
    slide.insertBefore(numberText, slide.firstChild);
  });

  const prevButton = document.querySelector('.prev');
  const nextButton = document.querySelector('.next');
  prevButton.addEventListener('click', function() {
    plusSlides(-1);
  });
  nextButton.addEventListener('click', function() {
    plusSlides(1);
  });

  const thumbnailPictures = document.querySelectorAll('.thumbnail-list picture');
  thumbnailPictures.forEach((picture, index) => {
    picture.addEventListener('click', function() {
      currentSlide(index + 1);
    });
  });

  showSlides(slideIndex);
});

function plusSlides(n) {
  showSlides(slideIndex += n);
}

function currentSlide(n) {
  showSlides(slideIndex = n);
}

function showSlides(n) {
  const slides = document.getElementsByClassName("mySlides");
  const thumbnails = document.getElementsByClassName("thumbnail");

  if (n > slides.length) { slideIndex = 1; }
  if (n < 1) { slideIndex = slides.length; }

  for (let i = 0; i < slides.length; i++) {
    slides[i].style.display = "none";
  }
  for (let i = 0; i < thumbnails.length; i++) {
    thumbnails[i].className = thumbnails[i].className.replace(" active", "");
  }

  slides[slideIndex - 1].style.display = "block";
  thumbnails[slideIndex - 1].className += " active";
}
